"""Produce the requested action report from sanitized remote harness output."""
import argparse,json,statistics,pathlib
p=argparse.ArgumentParser();p.add_argument('report');p.add_argument('output');p.add_argument('--label',default='Baseline');a=p.parse_args()
r=json.loads(pathlib.Path(a.report).read_text())
lines=[f'# {a.label}: mobile web actions', '', f"Measured {r['started']} from `h@backplane` to `{r['origin']}` across Tailscale. Installed source baseline: `273b268cd`. Chromium, 390×844 CSS pixels, touch, DPR 3, iPhone Safari UA. This is mobile emulation on a Linux CPU, **not Safari/iPhone hardware**.", '', 'First content is the first post-frame observation of the requested thread, bot header, or optimistic message. Settlement requires a ready reply for the destination and a subsequent paint; sends additionally require the committed row. A bot can paint a retained destination after its action response but before its open response.', '', '| Action | Cached | First content ms | Settled ms | View RPCs issued | Received reply bytes | Client JS ms | Layout ms | Style ms |', '|---|---|---:|---:|---:|---:|---:|---:|---:|']
for n,x in enumerate(r['actions']):
 b=x['browser'];name=x['action']+(' '+x['target'] if x.get('target') else (' (reply)' if n==len(r['actions'])-1 else ' (new message)'))
 fmt=lambda v:'timeout' if v is None else f'{v:.1f}'
 lines.append(f"| {name} | {'yes' if x['cached'] else 'no'} | {fmt(x['firstContentMs'])} | {fmt(x['settledMs'])} | {len(x['roundTrips'])} | {sum(y.get('bytes') or 0 for y in x['roundTrips'])} | {b['ScriptDuration']*1000:.1f} | {b['LayoutDuration']*1000:.1f} | {b['RecalcStyleDuration']*1000:.1f} |")
lines+=['', '## Request chains', '', 'Counts above include follow-up requests issued before settlement. The cold first-content path is one `view.open`; its extra `view.action:fab-look` is issued after content arrives. Cached bot switches prepare `view.action:bot` and then `view.open`. Send uses `view.action:send`, an ordinary send RPC, and a canonical `view.update`. The view RPC recorder counts only view requests; ordinary send RPCs are not included in its count.', '']
for x in r['actions']:
 chain=' → '.join(f"{y['method']} ({y.get('replyMs',0):.1f} ms, {y.get('bytes',0)} B)" if isinstance(y.get('replyMs'),(float,int)) else y['method']+' (reply after measurement boundary)' for y in x['roundTrips'])
 lines.append(f"- {x['action']} `{x.get('target') or 'TEST'}` cached={x['cached']}: {chain}.")
lines+=['', '## Network, server and rendering', '', f"Cold boot to usable sidebar: {r.get('bootMs',0):.1f} ms. Five independent `/hello` request durations: "+', '.join(f"{x['ms']:.1f}" for x in r['http'])+' ms. These include service queueing and cannot be called pure network RTT. The hub does not expose per-request Server-Timing, so precise network/server separation is unavailable on the installed baseline.', '', 'The first investigative run under heavier concurrent load measured cold opens at 3483–6779 ms, cached threads at 17–28 ms and `/hello` at 70–2144 ms. Its bot/send settlement detector was found to admit late prior-action paints; those settlement numbers are excluded. This repeat is fenced by actual destination and committed message. Both runs used the same installed source. Variability is material.', '', 'The table uses CDP cumulative ScriptDuration, LayoutDuration and RecalcStyleDuration deltas. The raw JSON also has per-function render/patch timing, decode time, layout/style counts, request/reply timestamps, and frame traces. Those client measurements overlap wall time and must not be added to request latency as independent spans.', '', 'Hub `/debug/perf.json` spans are process-wide aggregate service work since startup, including other active clients. They support attribution of busy service work but are not per-action measurements:', '', '| Server span | Samples | Mean ms | p99 upper bound ms | Max ms |', '|---|---:|---:|---:|---:|']
for x in r.get('serverPerf',{}).get('rows',[]):
 if x['name'] in ['hub.rpc','thin.rpc.1','thin.rpc.3','hub.tick','hub.tick.decide']:
  lines.append(f"| {x['name']} | {x['n']} | {x['mean']/1000:.1f} | {x['p99']/1000:.1f} | {x['max']/1000:.1f} |")
lines+=['', '## Coverage and cleanup', '', f"Five existing threads include long/running work and a short completed pairing thread. Two existing bots were viewed. Real sends/replies were confined to a newly created TEST conversation `{r.get('testThread','unavailable')}`. Pairing used the new single-use invitation enrollment endpoint. The independently enrolled TEST device was revoked: **{r['revoked']}**. No real device was revoked. Browser errors: "+str(r['errors'])+'.', '', 'Limitations: emulated DOM/frame observation approximates first paint; no physical iPhone trace was available. Browser input uses the same production delegated click/input handlers through DOM events, excluding Playwright selector/scroll delays. This run did not reload to test disk restoration, throttle the CPU to an iPhone, or include a deep paging acceptance suite. Raw reports remain in `build/instant-ui/`.']
lines[2:2]=['**Test isolation correction:** These historical measurements came from the live hub. The harness wrongly created six real test conversations there. A TEST label and device pairing did not isolate those writes. Do not repeat this procedure. The replacement runner creates its own loopback hub, throwaway home and stand-in agents; it accepts no hub address or pairing input. The six live threads are left untouched for auto-settle. These numbers are retained as historical observations, not isolated-test results.','']
pathlib.Path(a.output).write_text('\n'.join(lines)+'\n')
